```python
from cerebras.cloud.sdk import Cerebras
import base64
import mimetypes
import os
from pathlib import Path

api_key = os.environ["CEREBRAS_API_KEY"]
image_path = Path("screenshot.png")

if not image_path.is_file():
    raise FileNotFoundError(f"Image file not found: {image_path}")

mime_type, _ = mimetypes.guess_type(image_path.name)
if mime_type not in {"image/png", "image/jpeg"}:
    raise ValueError(f"Unsupported image type: {mime_type}. Only PNG and JPEG are supported.")

with image_path.open("rb") as image_file:
    base64_image = base64.b64encode(image_file.read()).decode("utf-8")

client = Cerebras(api_key=api_key)

response = client.chat.completions.create(
    model="gemma-4-31b",
    messages=[
        {
            "role": "user",
            "content": [
                {"type": "text", "text": "Describe this image in one concise sentence."},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:{mime_type};base64,{base64_image}"
                    },
                },
            ],
        }
    ],
)

content = response.choices[0].message.content
if isinstance(content, list):
    print("".join(part.get("text", "") if isinstance(part, dict) else str(part) for part in content).strip())
else:
    print(str(content).strip())
